inputs = ['ibcbk', 'gjay', 'acahix', 'hfu', 'ecf']
outputs = ['uvbczbk', 'gfwdafcz', 'aczahuvx', 'hfu', 'eczf']

# Let me think about this differently - what if I focus on transformations that affect multiple inputs?
print("Analyzing which characters appear in multiple positions:")
all_chars = {}
for i, inp in enumerate(inputs):
    for char in inp:
        if char not in all_chars:
            all_chars[char] = []
        all_chars[char].append((i, 'input'))

for i, out in enumerate(outputs):
    for char in out:
        if char not in all_chars:
            all_chars[char] = []
        all_chars[char].append((i, 'output'))

print("Character occurrences:")
for char, occurrences in all_chars.items():
    print(f"  '{char}': {occurrences}")

